'use client'

import { useEffect, useState } from 'react'
import { motion } from 'motion/react'
import TrafficMap from './traffic-map'

const RANGES = ['1h', '24h', '7d', '30d']
const fmt = (n) => (n >= 1e9 ? `${(n / 1e9).toFixed(2)}B` : n >= 1e6 ? `${(n / 1e6).toFixed(2)}M` : n >= 1e3 ? `${(n / 1e3).toFixed(1)}k` : `${Math.round(n)}`)
const spark = (seed) => Array.from({ length: 20 }, (_, i) => 0.45 + Math.sin(i * 0.7 + seed) * 0.22 + ((i * seed * 7) % 10) / 45)

function Stat({ label, value, unit = '', delta, seed, live }) {
  const [v, setV] = useState(value)
  useEffect(() => {
    setV(value)
    if (!live) return
    const id = setInterval(() => !document.hidden && setV((x) => x * (1 + Math.random() * 0.002)), 1000)
    return () => clearInterval(id)
  }, [value, live])
  const pts = spark(seed)
  const d = pts.map((p, i) => `${i ? 'L' : 'M'}${(i / 19) * 100},${30 - p * 28}`).join('')
  return (
    <div className="rounded-xl border border-line bg-panel p-4">
      <div className="flex items-center justify-between text-xs"><span className="text-mute">{label}</span><span className={delta >= 0 ? 'text-emerald-400' : 'text-rose-400'}>{delta >= 0 ? '▲' : '▼'} {Math.abs(delta)}%</span></div>
      <div className="mt-2 font-mono text-2xl tabular-nums tracking-tight text-tx">{fmt(v)}<span className="ml-1 text-sm text-faint">{unit}</span></div>
      <svg viewBox="0 0 100 30" className="mt-2 h-8 w-full" preserveAspectRatio="none">
        <motion.path d={d} fill="none" stroke="#ff6a2b" strokeWidth="1.5" vectorEffect="non-scaling-stroke" initial={{ pathLength: 0 }} animate={{ pathLength: 1 }} transition={{ duration: 1.2, ease: 'easeOut' }} />
      </svg>
    </div>
  )
}

const TOP = [['IN', 'India', 34.1], ['US', 'United States', 26.8], ['DE', 'Germany', 11.9], ['BR', 'Brazil', 9.2], ['SG', 'Singapore', 6.7]]

// Block: an edge analytics dashboard with live stats, a request map and top countries.
export default function EdgeDashboard({ title = 'Traffic overview' }) {
  const [range, setRange] = useState('24h')
  const k = RANGES.indexOf(range) + 1
  return (
    <section className="@container w-full rounded-2xl border border-line bg-bg p-3 @2xl:p-5">
      <header className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-2.5">
          <span className="grid size-7 place-items-center rounded-lg bg-acc/15 text-acc"><svg viewBox="0 0 24 24" className="size-4" fill="none" stroke="currentColor" strokeWidth="2"><path d="M3 12h4l3-8 4 16 3-8h4" /></svg></span>
          <div><div className="text-sm font-medium leading-5 text-tx">{title}</div><div className="flex items-center gap-1.5 text-[11px] leading-4 text-mute"><span className="size-1.5 rounded-full bg-emerald-400" />Live</div></div>
        </div>
        <div className="flex rounded-lg border border-line2 bg-panel p-0.5">
          {RANGES.map((r) => (
            <button key={r} type="button" onClick={() => setRange(r)} className="relative px-3 py-1 text-xs">
              {range === r && <motion.span layoutId="ed-range" className="absolute inset-0 rounded-md bg-line2" transition={{ type: 'spring', stiffness: 480, damping: 34 }} />}
              <span className={`relative ${range === r ? 'text-tx' : 'text-mute'}`}>{r}</span>
            </button>
          ))}
        </div>
      </header>
      <div className="mt-4 grid grid-cols-2 gap-2 @4xl:grid-cols-4">
        <Stat label="Requests" value={4.82e6 * k * k} delta={12.4} seed={1} live />
        <Stat label="Bandwidth" value={318e3 * k * k} unit="MB" delta={8.1} seed={2} />
        <Stat label="Threats blocked" value={18244 * k} delta={-3.2} seed={3} live />
        <Stat label="Cache hit" value={91} unit="%" delta={1.6} seed={4} />
      </div>
      <div className="mt-2 grid gap-2 @4xl:grid-cols-[1fr_260px]">
        <div className="rounded-xl border border-line bg-panel p-4">
          <div className="mb-3 flex items-center justify-between text-xs"><span className="text-tx">Traffic by edge location</span><span className="flex items-center gap-1.5 text-mute"><span className="size-1.5 animate-pulse rounded-full bg-acc" />Live</span></div>
          <TrafficMap />
        </div>
        <div className="rounded-xl border border-line bg-panel p-4">
          <div className="mb-3 text-xs text-tx">Top countries</div>
          <ul className="space-y-3">
            {TOP.map(([cc, name, v], i) => (
              <li key={cc} className="text-xs">
                <div className="flex justify-between"><span className="text-tx"><span className="mr-2 font-mono text-[10px] text-faint">{cc}</span>{name}</span><span className="font-mono text-mute">{v}%</span></div>
                <div className="mt-1.5 h-1 overflow-hidden rounded-full bg-line"><motion.div className="h-full rounded-full bg-acc" initial={{ width: 0 }} animate={{ width: `${(v / 34.1) * 100}%` }} transition={{ delay: 0.2 + i * 0.08, type: 'spring', stiffness: 90, damping: 18 }} /></div>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </section>
  )
}

'use client'

import { useEffect, useRef } from 'react'
import { worldDots, project, COLS, ROWS } from './world-dots'

const HUBS = [
  { id: 'BOM', lat: 19.07, lon: 72.87 }, { id: 'FRA', lat: 50.11, lon: 8.68 }, { id: 'IAD', lat: 38.95, lon: -77.45 },
  { id: 'SFO', lat: 37.62, lon: -122.38 }, { id: 'SIN', lat: 1.35, lon: 103.99 }, { id: 'GRU', lat: -23.43, lon: -46.47 },
  { id: 'NRT', lat: 35.77, lon: 140.39 }, { id: 'SYD', lat: -33.94, lon: 151.18 }, { id: 'JNB', lat: -26.14, lon: 28.24 },
  { id: 'LHR', lat: 51.47, lon: -0.45 }, { id: 'DXB', lat: 25.25, lon: 55.36 },
]

// Cloudflare-style dotted world map with live request arcs between edge locations.
export default function TrafficMap({ hubs = HUBS, arcs = 7, color = '255,106,43', className = '' }) {
  const ref = useRef(null)
  useEffect(() => {
    const c = ref.current
    const ctx = c?.getContext('2d')
    if (!ctx || !hubs?.length) return
    const dots = worldDots()
    let w = 0, h = 0, raf, last = performance.now()
    const size = () => {
      const d = Math.min(window.devicePixelRatio || 1, 2)
      w = c.clientWidth; h = c.clientHeight
      c.width = Math.max(1, w * d); c.height = Math.max(1, h * d); ctx.setTransform(d, 0, 0, d, 0, 0)
    }
    size()
    const ro = new ResizeObserver(size); ro.observe(c)
    const pick = () => {
      const a = hubs[(Math.random() * hubs.length) | 0]
      let b = a
      while (b === a && hubs.length > 1) b = hubs[(Math.random() * hubs.length) | 0]
      return { a, b, t: -Math.random() * 1.2, speed: 0.35 + Math.random() * 0.3 }
    }
    const live = Array.from({ length: arcs }, pick)
    const flashes = []
    const pos = (p) => project(p.lat, p.lon, w, h)
    const bez = (A, B, t) => {
      const mx = (A[0] + B[0]) / 2, my = (A[1] + B[1]) / 2 - Math.hypot(B[0] - A[0], B[1] - A[1]) * 0.35
      const u = 1 - t
      return [u * u * A[0] + 2 * u * t * mx + t * t * B[0], u * u * A[1] + 2 * u * t * my + t * t * B[1]]
    }
    const draw = (now) => {
      const dt = Math.min(0.05, (now - last) / 1000); last = now
      ctx.clearRect(0, 0, w, h)
      const pitch = w / COLS, r = Math.max(0.6, pitch * 0.26)
      ctx.fillStyle = document.documentElement.classList.contains('light') ? 'rgba(20,20,23,0.22)' : 'rgba(237,237,239,0.16)'
      for (const d of dots) {
        const x = (d.col + 0.5) * pitch, y = (d.row + 0.5) * (h / ROWS)
        ctx.beginPath(); ctx.arc(x, y, r, 0, 6.283); ctx.fill()
      }
      for (const arc of live) {
        arc.t += dt * arc.speed
        if (arc.t > 1.35) { flashes.push({ p: arc.b, t: 0 }); Object.assign(arc, pick(), { t: 0 }) }
        if (arc.t <= 0) continue
        const A = pos(arc.a), B = pos(arc.b)
        const head = Math.min(1, arc.t), tail = Math.max(0, Math.min(1, arc.t - 0.35))
        ctx.lineWidth = 1.2; ctx.lineCap = 'round'
        const steps = 24
        for (let i = 0; i < steps; i++) {
          const t0 = tail + ((head - tail) * i) / steps, t1 = tail + ((head - tail) * (i + 1)) / steps
          const p0 = bez(A, B, t0), p1 = bez(A, B, t1)
          ctx.strokeStyle = `rgba(${color},${(i / steps) * 0.9})`
          ctx.beginPath(); ctx.moveTo(p0[0], p0[1]); ctx.lineTo(p1[0], p1[1]); ctx.stroke()
        }
        if (arc.t < 1) { const p = bez(A, B, head); ctx.fillStyle = `rgb(${color})`; ctx.beginPath(); ctx.arc(p[0], p[1], 1.8, 0, 6.283); ctx.fill() }
      }
      for (let i = flashes.length - 1; i >= 0; i--) {
        const f = flashes[i]; f.t += dt * 1.4
        if (f.t > 1) { flashes.splice(i, 1); continue }
        const [x, y] = pos(f.p)
        ctx.strokeStyle = `rgba(${color},${1 - f.t})`; ctx.lineWidth = 1
        ctx.beginPath(); ctx.arc(x, y, 2 + f.t * 14, 0, 6.283); ctx.stroke()
      }
      for (const hub of hubs) {
        const [x, y] = pos(hub)
        ctx.fillStyle = `rgba(${color},0.25)`; ctx.beginPath(); ctx.arc(x, y, 4, 0, 6.283); ctx.fill()
        ctx.fillStyle = `rgb(${color})`; ctx.beginPath(); ctx.arc(x, y, 1.8, 0, 6.283); ctx.fill()
      }
      raf = requestAnimationFrame(draw)
    }
    raf = requestAnimationFrame(draw)
    return () => { cancelAnimationFrame(raf); ro.disconnect() }
  }, [hubs, arcs, color])
  return (
    <div className={`relative w-full ${className}`} style={{ aspectRatio: `${COLS} / ${ROWS}` }}>
      <canvas ref={ref} className="absolute inset-0 size-full" aria-label="Live traffic map" role="img" />
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { motion, useMotionTemplate, useMotionValue } from 'motion/react'

function Tile({ className = '', title, body, children }) {
  const x = useMotionValue(-300), y = useMotionValue(-300)
  const bg = useMotionTemplate`radial-gradient(220px circle at ${x}px ${y}px, rgba(255,106,43,.10), transparent 70%)`
  return (
    <div onPointerMove={(e) => { const r = e.currentTarget.getBoundingClientRect(); x.set(e.clientX - r.left); y.set(e.clientY - r.top) }} onPointerLeave={() => { x.set(-300); y.set(-300) }}
      className={`relative overflow-hidden rounded-2xl border border-line bg-panel ${className}`}>
      <motion.div className="pointer-events-none absolute inset-0" style={{ background: bg }} />
      <div className="relative flex h-full flex-col">
        <div className="relative min-h-36 flex-1">{children}</div>
        <div className="p-5 pt-0"><h3 className="text-[15px] font-medium text-tx">{title}</h3><p className="mt-1 text-sm text-mute">{body}</p></div>
      </div>
    </div>
  )
}

function Regions() {
  const [on, setOn] = useState(0)
  useEffect(() => { const id = setInterval(() => setOn((n) => (n + 1) % 12), 500); return () => clearInterval(id) }, [])
  return <div className="absolute inset-0 grid place-items-center p-6"><div className="grid grid-cols-6 gap-2">{Array.from({ length: 12 }, (_, i) => <motion.span key={i} animate={{ backgroundColor: i === on ? '#ff6a2b' : '#1e1e22', scale: i === on ? 1.1 : 1 }} className="size-7 rounded-md @3xl:size-8" />)}</div></div>
}
function Rollback() {
  const [v, setV] = useState(3)
  useEffect(() => { const id = setInterval(() => setV((n) => (n === 3 ? 2 : 3)), 1800); return () => clearInterval(id) }, [])
  return (
    <div className="absolute inset-0 flex items-center justify-center gap-2 p-6">
      {[1, 2, 3].map((n) => (
        <motion.div key={n} animate={{ opacity: n === v ? 1 : 0.35, y: n === v ? -6 : 0, borderColor: n === v ? '#ff6a2b' : '#2a2a30' }} className="rounded-lg border bg-bg px-3 py-2 font-mono text-xs text-tx">v1.{n}</motion.div>
      ))}
    </div>
  )
}
function Logs() {
  const [lines, setLines] = useState([0, 1, 2, 3])
  useEffect(() => { const id = setInterval(() => setLines((l) => [...l.slice(1), l[l.length - 1] + 1]), 700); return () => clearInterval(id) }, [])
  const txt = ['GET /api/user 200 12ms', 'POST /checkout 201 48ms', 'GET / 304 3ms', 'GET /img/hero.webp 200 9ms', 'GET /api/search 200 21ms']
  return <div className="absolute inset-0 overflow-hidden p-5 font-mono text-[11px] text-mute">{lines.map((n) => <motion.div key={n} layout initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="py-0.5"><span className="text-faint">{String(10 + (n % 50)).padStart(2, '0')}:04</span> {txt[n % txt.length]}</motion.div>)}</div>
}
function Shield() {
  return (
    <div className="absolute inset-0 grid place-items-center">
      <motion.svg viewBox="0 0 24 24" className="size-16 text-acc" fill="none" stroke="currentColor" strokeWidth="1.2"><motion.path d="M12 3 4 6v6c0 5 3.5 8 8 9 4.5-1 8-4 8-9V6z" initial={{ pathLength: 0 }} animate={{ pathLength: 1 }} transition={{ duration: 1.6, repeat: Infinity, repeatType: 'reverse', repeatDelay: 0.6 }} /><path d="m9 12 2 2 4-4" /></motion.svg>
    </div>
  )
}

// Block: a four-tile feature section. Every tile has its own small live demo.
export default function FeatureBento() {
  return (
    <section className="@container w-full">
      <div className="grid gap-3 @3xl:grid-cols-3">
        <Tile className="@3xl:col-span-2" title="Runs in every region" body="Your code is copied to each edge location on deploy."><Regions /></Tile>
        <Tile title="Instant rollback" body="One click back to any previous build."><Rollback /></Tile>
        <Tile title="Built-in firewall" body="Bad traffic stops before it reaches you."><Shield /></Tile>
        <Tile className="@3xl:col-span-2" title="Real-time logs" body="Tail requests as they happen, no setup."><Logs /></Tile>
      </div>
    </section>
  )
}

'use client'

import { useEffect, useRef } from 'react'
import { worldDots } from './world-dots'

const HUBS = [[19.07, 72.87], [50.11, 8.68], [38.95, -77.45], [1.35, 103.99], [-23.43, -46.47], [35.77, 140.39], [-33.94, 151.18], [25.25, 55.36]]
const rad = Math.PI / 180
const vec = (lat, lon) => [Math.cos(lat * rad) * Math.sin(lon * rad), Math.sin(lat * rad), Math.cos(lat * rad) * Math.cos(lon * rad)]
const slerp = (a, b, t) => {
  const d = Math.acos(Math.max(-1, Math.min(1, a[0] * b[0] + a[1] * b[1] + a[2] * b[2])))
  if (d < 1e-4) return a
  const s = Math.sin(d), k0 = Math.sin((1 - t) * d) / s, k1 = Math.sin(t * d) / s
  return [a[0] * k0 + b[0] * k1, a[1] * k0 + b[1] * k1, a[2] * k0 + b[2] * k1]
}

// Rotating dotted globe of real land masses with arcs between edge locations. Drag to spin.
export default function EdgeGlobe({ size = 320, hubs = HUBS, speed = 0.18, color = '255,106,43' }) {
  const ref = useRef(null)
  useEffect(() => {
    const c = ref.current
    const ctx = c?.getContext('2d')
    if (!ctx) return
    const d = Math.min(window.devicePixelRatio || 1, 2)
    c.width = size * d; c.height = size * d; ctx.setTransform(d, 0, 0, d, 0, 0)
    const pts = worldDots().map((p) => vec(p.lat, p.lon))
    const H = hubs.map(([la, lo]) => vec(la, lo))
    const arcs = Array.from({ length: Math.min(5, H.length) }, (_, i) => ({ a: i % H.length, b: (i * 3 + 2) % H.length, t: -i * 0.3 }))
    let rot = -1.3, raf, last = performance.now(), drag = null
    const R = size * 0.44, cx = size / 2, cy = size / 2, tilt = -0.3
    const proj = ([x, y, z], lift = 1) => {
      const X = x * Math.cos(rot) + z * Math.sin(rot), Z = -x * Math.sin(rot) + z * Math.cos(rot)
      const Y = y * Math.cos(tilt) - Z * Math.sin(tilt), Z2 = y * Math.sin(tilt) + Z * Math.cos(tilt)
      return [cx + X * R * lift, cy - Y * R * lift, Z2]
    }
    const draw = (now) => {
      const dt = Math.min(0.05, (now - last) / 1000); last = now
      if (!drag) rot += speed * dt
      ctx.clearRect(0, 0, size, size)
      const lite = document.documentElement.classList.contains('light')
      const g = ctx.createRadialGradient(cx - R * 0.3, cy - R * 0.3, R * 0.1, cx, cy, R)
      if (lite) { g.addColorStop(0, '#ffffff'); g.addColorStop(1, '#e8e8ec') } else { g.addColorStop(0, '#16161a'); g.addColorStop(1, '#0b0b0d') }
      ctx.fillStyle = g; ctx.beginPath(); ctx.arc(cx, cy, R, 0, 6.283); ctx.fill()
      ctx.strokeStyle = lite ? 'rgba(20,20,23,0.16)' : 'rgba(237,237,239,0.08)'; ctx.stroke()
      for (const p of pts) {
        const [x, y, z] = proj(p)
        if (z < 0) continue
        ctx.fillStyle = lite ? `rgba(20,20,23,${0.14 + z * 0.5})` : `rgba(237,237,239,${0.1 + z * 0.45})`
        ctx.fillRect(x - 0.8, y - 0.8, 1.6, 1.6)
      }
      for (const arc of arcs) {
        arc.t += dt * 0.4
        if (arc.t > 1.4) { arc.t = 0; arc.a = arc.b; arc.b = (arc.b + 1 + ((Math.random() * (H.length - 1)) | 0)) % H.length }
        if (arc.t <= 0) continue
        const head = Math.min(1, arc.t), tail = Math.max(0, arc.t - 0.4)
        for (let i = 0; i < 20; i++) {
          const t0 = tail + ((head - tail) * i) / 20, t1 = tail + ((head - tail) * (i + 1)) / 20
          const l0 = 1 + Math.sin(t0 * Math.PI) * 0.18, l1 = 1 + Math.sin(t1 * Math.PI) * 0.18
          const p0 = proj(slerp(H[arc.a], H[arc.b], t0), l0), p1 = proj(slerp(H[arc.a], H[arc.b], t1), l1)
          if (p0[2] < -0.1 || p1[2] < -0.1) continue
          ctx.strokeStyle = `rgba(${color},${(i / 20) * 0.95})`; ctx.lineWidth = 1.3
          ctx.beginPath(); ctx.moveTo(p0[0], p0[1]); ctx.lineTo(p1[0], p1[1]); ctx.stroke()
        }
      }
      const pulse = (now / 1600) % 1
      for (const h of H) {
        const [x, y, z] = proj(h)
        if (z < 0) continue
        ctx.strokeStyle = `rgba(${color},${(1 - pulse) * 0.7 * z})`
        ctx.beginPath(); ctx.arc(x, y, 2 + pulse * 9, 0, 6.283); ctx.stroke()
        ctx.fillStyle = `rgb(${color})`; ctx.beginPath(); ctx.arc(x, y, 2, 0, 6.283); ctx.fill()
      }
      raf = requestAnimationFrame(draw)
    }
    raf = requestAnimationFrame(draw)
    const down = (e) => { drag = e.clientX; c.setPointerCapture?.(e.pointerId) }
    const move = (e) => { if (drag !== null) { rot += (e.clientX - drag) * 0.008; drag = e.clientX } }
    const up = () => { drag = null }
    c.addEventListener('pointerdown', down); c.addEventListener('pointermove', move)
    c.addEventListener('pointerup', up); c.addEventListener('pointercancel', up)
    return () => {
      cancelAnimationFrame(raf)
      c.removeEventListener('pointerdown', down); c.removeEventListener('pointermove', move)
      c.removeEventListener('pointerup', up); c.removeEventListener('pointercancel', up)
    }
  }, [size, hubs, speed, color])
  return <canvas ref={ref} style={{ width: size, height: size }} className="cursor-grab touch-none active:cursor-grabbing" role="img" aria-label="Rotating globe" />
}

'use client'

import { useState } from 'react'
import { motion, AnimatePresence } from 'motion/react'

const ENTRIES = [
  { v: '2.4.0', d: 'Sep 22', tag: 'Feature', t: 'Traffic map in the dashboard', b: ['Live arcs between edge locations', 'Filter by country and status code'] },
  { v: '2.3.2', d: 'Sep 15', tag: 'Fix', t: 'Faster cold starts', b: ['Median cold start down to 12 ms', 'Smaller runtime bundle'] },
  { v: '2.3.0', d: 'Sep 02', tag: 'Feature', t: 'Instant rollback', b: ['Roll back to any build in one click', 'Keeps environment variables in sync'] },
]
const TONE = { Feature: 'bg-acc/15 text-acc', Fix: 'bg-emerald-400/10 text-emerald-300' }

// Block: product changelog on a timeline. Entries expand in place.
export default function ChangelogFeed({ entries = ENTRIES }) {
  const [open, setOpen] = useState(0)
  return (
    <section className="@container w-full rounded-2xl border border-line bg-bg p-6">
      <h2 className="text-xl font-semibold tracking-tight text-tx">Changelog</h2>
      <ol className="relative mt-6 border-l border-line pl-6">
        {entries.map((e, i) => (
          <li key={e.v} className="relative pb-6 last:pb-0">
            <motion.span animate={{ scale: open === i ? 1.3 : 1, backgroundColor: open === i ? '#ff6a2b' : '#2a2a30' }} className="absolute -left-[29px] top-1.5 size-2.5 rounded-full ring-4 ring-bg" />
            <button type="button" onClick={() => setOpen(open === i ? -1 : i)} aria-expanded={open === i} className="w-full text-left">
              <div className="flex flex-wrap items-center gap-2 text-xs"><span className="font-mono text-tx">v{e.v}</span><span className="text-faint">{e.d}</span><span className={`rounded-full px-2 py-0.5 text-[10px] ${TONE[e.tag] || 'bg-line text-mute'}`}>{e.tag}</span></div>
              <div className="mt-1 text-[15px] text-tx">{e.t}</div>
            </button>
            <AnimatePresence initial={false}>
              {open === i && (
                <motion.ul initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={{ type: 'spring', stiffness: 300, damping: 32 }} className="overflow-hidden">
                  {e.b.map((b) => <li key={b} className="mt-2 flex gap-2 text-sm text-mute"><span className="text-faint">-</span>{b}</li>)}
                </motion.ul>
              )}
            </AnimatePresence>
          </li>
        ))}
      </ol>
    </section>
  )
}

'use client'

import { useState } from 'react'
import { motion, AnimatePresence } from 'motion/react'

const valid = (v) => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v)

// Block: magic-link sign-in. Validates as you type, shakes on a bad address, confirms with a sent state.
/** @param {{ product?: any, onSubmit?: any }} props */
