export default function TetherTag({ label = '30% off', sub = 'Launch week', color = '#ff6a2b', links = 12, className = '' }) {
  const host = useCanvasLoop((ctx, s) => {
    const n = clamp(Math.round(Number(links) || 12), 4, 30)
