        ctx.lineCap = 'round'
        const diag = Math.hypot(s.w, s.h)
        for (let y = g / 2; y < s.h; y += g) for (let x = g / 2; x < s.w; x += g) {
          const dx = mx - x, dy = my - y, d = Math.hypot(dx, dy) || 1
          const near = Math.max(0, 1 - d / (diag * 0.45))
          const len = 3 + near * g * 0.45
