function KeyCap({ def, pressed, backlit, onPress }) {
  const base = {
    ...capBase,
    position: 'relative',
    userSelect: 'none',
    overflow: 'hidden',
    borderRadius: '0.75cqw',
    border: '1px solid #d3d3d1',
