const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/

function Avatar({ person, first }) {
  return (
    <motion.div
      layout
      initial={{ opacity: 0, scale: 0.4, x: -16 }}
      animate={{ opacity: 1, scale: 1, x: 0 }}
      exit={{ opacity: 0, scale: 0.4, x: 16 }}
      transition={{ type: 'spring', stiffness: 380, damping: 26 }}
      whileHover={{ scale: 1.12 }}
      className="relative grid size-9 shrink-0 place-items-center overflow-hidden rounded-full border-2 border-bg bg-panel2 text-[11px] font-semibold text-mute"
